-- Synthetic AUTH context; real PostgreSQL roles/RLS. No concurrent-session claim.
begin;
set local search_path=public,extensions;
select plan(105);
create function pg_temp.as_user(n integer) returns void language plpgsql as $$ begin perform set_config('request.jwt.claims',jsonb_build_object('sub',lpad(n::text,8,'0')||'-0000-4000-8000-000000000000','is_anonymous',false)::text,true); end $$;
insert into auth.users(id,email_confirmed_at) select (lpad(n::text,8,'0')||'-0000-4000-8000-000000000000')::uuid,case when n=7 then null else now() end from generate_series(1,8) n;
insert into public.account_profiles(user_id,role,name,area,language) select id,case when left(id::text,8)::integer in (1,2,5,7,8) then 'elder' else 'volunteer' end,'SECRET PERSON '||id::text,'SECRET PRECISE PROFILE AREA','en' from auth.users;
insert into public.pilot_communities(id,label,coarse_area,enabled) values('aaaaaaaa-0000-4000-8000-000000000000','Closed pilot','Owner configured district',true);
insert into public.pilot_memberships(user_id,community_id,role,status) select user_id,'aaaaaaaa-0000-4000-8000-000000000000',role,case when left(user_id::text,8)::integer=5 then 'pending' when left(user_id::text,8)::integer=6 then 'revoked' else 'approved' end from public.account_profiles;
update auth.users set is_anonymous=true where id='00000008-0000-4000-8000-000000000000';
insert into public.pilot_task_policies(category,enabled,approved_credit_minutes,needed_skills) values('yard',true,45,array['yard']),('household',true,null,array['general']);
set local role authenticated;
do $$ begin perform pg_temp.as_user(1); end $$;
